/* demo.c是接待员：读三项输入、请计算者做事、把账本展示给人。 */
#include "timing.h"
#include <stdio.h>

int main(void) {
    float speed_mps; /* 车速是m/s，不是之前CAN课的km/h；10m/s=36km/h。 */
    int skip_tick, late_ms;
    /* %f读float，%d读int；&给出变量存放位置，scanf才能写进去。 */
    if (scanf("%f %d %d", &speed_mps, &skip_tick, &late_ms) != 3) return 1;
    struct Timeline result = {0}; /* main的结果账本，目前全0。 */
    int status = Timeline_Run(speed_mps, skip_tick, late_ms, &result);
    printf("status=%d\nvalid=%d\n", status, status == 0);
    if (status != 0) return 0; /* 参数被拒绝，不能把旧账本当成新结果展示。 */
    printf("control_ms=");
    for (int i=0; i<result.control_count; ++i) printf("%d%s",result.control_ms[i],i+1==result.control_count?"\n":",");
    printf("dt_ms=");
    for (int i=0; i<result.control_count; ++i) printf("%d%s",result.dt_ms[i],i+1==result.control_count?"\n":",");
    printf("perception_ms=");
    for (int i=0; i<result.perception_count; ++i) printf("%d%s",result.perception_ms[i],i+1==result.perception_count?"\n":",");
    /* ?:是选择字符串：最后一项换行，其余逗号；与计算dt无关。 */
    printf("control_count=%d\nupdate_count=%d\nperception_count=%d\n",result.control_count,result.control_count-1,result.perception_count);
    printf("fixed_distance_m=%.6f\nmeasured_distance_m=%.6f\n",result.fixed_distance_m,result.measured_distance_m);
    return 0;
}

/* 附录的独立入口；主课demo只读三项，不必先理解这里五项。 */
#include "signal.h"
#include <stdio.h>
int main(void) {
    struct VehicleSignal s = {0};
    long now_ms;
    if (scanf("%f %ld %ld %d %d",&s.value_mps,&now_ms,&s.stamp_ms,&s.valid,&s.source)!=5) return 1;
    int status=Signal_Check(&s,now_ms);
    printf("status=%d\nvalid=%d\n",status,status==0);
    if (status==0 || status==-4) printf("age_ms=%ld\n",now_ms-s.stamp_ms);
    return 0;
}

/* 附录：数据年龄=当前时刻-数据标记时刻，不是主课两次运行之间的dt。 */
#include "signal.h"
#include <stddef.h>
#include <math.h>
int Signal_Check(const struct VehicleSignal *signal, long now_ms) {
    if (signal == NULL) return -1;
    /* ->用于通过指针查看对象成员，等价于(*signal).valid这类写法。 */
    if (signal->valid != 1 || (signal->source != 1 && signal->source != 2)) return -2;
    if (!isfinite(signal->value_mps) || signal->value_mps<0 || signal->value_mps>50) return -2;
    /* 本演示先限制范围，再相减，避免一般超大long相减溢出。 */
    if (now_ms<0 || now_ms>1000000L || signal->stamp_ms<0 || signal->stamp_ms>1000000L) return -2;
    if (signal->stamp_ms > now_ms) return -3;
    long age_ms = now_ms - signal->stamp_ms;
    if (age_ms > 100L) return -4; /* 恰好100ms允许；101ms拒绝。 */
    return 0;
}

/* 附录：补回原计划D08，不属于D09主课的必做实作。 */
#ifndef ASW_SIGNAL_H
#define ASW_SIGNAL_H
struct VehicleSignal {
    float value_mps; /* 数值，例如10m/s。 */
    long stamp_ms;   /* 这份数据被标记的时刻；long是有符号整数，至少32位。 */
    int valid;       /* 1表示发送方认为有效；0表示无效。 */
    int source;      /* 本例1=雷达、2=车辆；0=未知，拒绝。 */
};
/* 0新鲜；-1空地址；-2字段非法；-3未来时间戳；-4年龄超过100ms。 */
int Signal_Check(const struct VehicleSignal *signal, long now_ms);
#endif

/* 附录自己的测试入口，主课不开启附录时不构建。 */
#include "signal.h"
#include <stddef.h>
int main(void) {
    struct VehicleSignal s = {10.0f,950L,1,1};
    if (Signal_Check(&s,1000L)!=0) return 1;
    s.stamp_ms=900L; if (Signal_Check(&s,1000L)!=0) return 2;
    s.stamp_ms=899L; if (Signal_Check(&s,1000L)!=-4) return 3;
    s.stamp_ms=1001L; if (Signal_Check(&s,1000L)!=-3) return 4;
    s.stamp_ms=950L;s.valid=0; if (Signal_Check(&s,1000L)!=-2) return 5;
    s.valid=1;s.source=0; if (Signal_Check(&s,1000L)!=-2) return 6;
    if (Signal_Check(NULL,1000L)!=-1) return 7;
    return 0;
}

/* 独立测试员：不用键盘，给固定输入，按自己算的预期检查。 */
#include "timing.h"
#include <math.h> /* fabsf把float差值取绝对值，允许小量浮点舍入误差。 */
#include <stdio.h>
#include <stddef.h>

int main(void) {
    struct Timeline r = {0};
    int status = Timeline_Run(10.0f,-1,0,&r);
    if (status != 0 || r.control_count != 7 || r.perception_count != 4 || fabsf(r.measured_distance_m-0.6f)>0.0001f) return 1;
    status = Timeline_Run(10.0f,3,0,&r);
    if (status != 0 || r.control_ms[3] != 40 || r.dt_ms[3] != 20 || fabsf(r.fixed_distance_m-0.5f)>0.0001f || fabsf(r.measured_distance_m-0.6f)>0.0001f) return 2;
    status = Timeline_Run(10.0f,-1,5,&r);
    if (status != 0 || r.control_ms[3] != 35 || r.dt_ms[3] != 15 || r.dt_ms[4] != 5) return 3;
    status = Timeline_Run(10.0f,3,0,&r);
    if (status != 0 || r.perception_ms[0] != 0 || r.perception_ms[1] != 20 || r.perception_ms[2] != 40 || r.perception_ms[3] != 60) return 4;
    /* 失败不能破坏之前的账本；比较具体成员，不比较含可能填充字节的整个struct。 */
    status = Timeline_Run(-1.0f,-1,0,&r);
    if (status != -2 || r.control_count != 6 || r.control_ms[3] != 40) return 5;
    status = Timeline_Run(10.0f,-1,0,NULL);
    if (status != -1) return 6;
    status = Timeline_Run(10.0f,0,0,&r);
    if (status != -2) return 7;
    printf("checks_passed=7\n");
    return 0;
}

/* timing.c是做计算的人；没有main，不决定从键盘还是网页拿输入。 */
#include "timing.h"
#include <stddef.h> /* NULL：没有可写对象的地址。 */
#include <math.h>   /* isfinite：普通有限数为真，NaN/正负无限为假。 */

int Timeline_Run(float speed_mps, int skip_tick, int late_ms, struct Timeline *out) {
    /* [1 检查再开始] ||表示或者；!表示把真/假反过来。 */
    if (out == NULL) return -1;
    if (!isfinite(speed_mps) || speed_mps < 0 || speed_mps > 50) return -2;
    if (skip_tick != -1 && (skip_tick < 1 || skip_tick > 5)) return -2;
    if (late_ms < 0 || late_ms > 9) return -2;

    /* [2 自己先写草稿] {0}使成员从0开始；只有全部做完才交回out。 */
    struct Timeline draft = {0};
    int last_control_ms = 0;
    /* [3 纸面时刻表] tick取0/1/2/3/4/5/6，计划时刻=0/10/.../60ms。 */
    for (int tick = 0; tick <= 6; ++tick) {
        int scheduled_ms = tick * 10;
        /* 观察员每20ms一次。%是求余：偶数tick除2余0。
         * 先记录观察员，所以漏掉控制更新不会让观察员也消失。 */
        if (tick % 2 == 0) {
            draft.perception_ms[draft.perception_count] = scheduled_ms;
            ++draft.perception_count;
        }
        /* continue是跳过这一轮剩余内容，进入下一轮；不是结束整个函数。 */
        if (tick == skip_tick) continue;
        int now_ms = scheduled_ms;
        if (tick == 3) now_ms = now_ms + late_ms;
        /* [4 到场就记一行] .访问本地draft里的成员。 */
        int index = draft.control_count;
        draft.control_ms[index] = now_ms;
        if (index > 0) { /* 第一次0ms只定起点；没有上一段可累加。 */
            int elapsed_ms = now_ms - last_control_ms;
            draft.dt_ms[index] = elapsed_ms;
            /* 毫秒变秒要除1000.0f，不能整数相除把10/1000截成0。 */
            float dt_s = (float)elapsed_ms / 1000.0f;
            /* +=表示“旧值加右边，再存回”。m/s乘s得到m。 */
            draft.fixed_distance_m += speed_mps * 0.010f;
            draft.measured_distance_m += speed_mps * dt_s;
        }
        /* 必须在算完差值后，才把本次时刻作为下一次的“上次”。 */
        last_control_ms = now_ms;
        ++draft.control_count;
    }
    /* [5 正式交回] *out代表调用者提供的整个对象；同类结构体可整体赋值。 */
    *out = draft;
    return 0;
}

/* timing.h像工作说明卡：约定输入和记账本的格式；这里不做计算。 */
#ifndef ASW_TIMING_H
#define ASW_TIMING_H

/* struct把相关数据装进同一本账，不是多个同时运行的程序。
 * control_ms记控制任务到场时间；dt_ms记距上次到场隔了多久，单位ms。
 * 第0项是0ms初始化，不做位移累加；最多7次到场，数组容量就是7。
 * perception_ms记另一位“观察员”在0/20/40/60ms到场。 */
struct Timeline {
    int control_ms[7];
    int dt_ms[7];
    int perception_ms[4];
    int control_count;
    int perception_count;
    float fixed_distance_m;    /* 每次都假装只过10ms的对照算法。 */
    float measured_distance_m; /* 根据两次到场时间差累加。 */
};

/* speed_mps单位m/s，允许0—50；skip_tick=-1表示不漏，1—5表示漏第几次。
 * late_ms=0—9，只把原定30ms那次控制更新推迟这么多毫秒。
 * return0成功；-1空输出地址；-2参数非法。失败不改调用者的账本。 */
int Timeline_Run(float speed_mps, int skip_tick, int late_ms, struct Timeline *out);
#endif

